package pl.takma.magazyn;
import android.app.Activity;import android.content.Intent;import android.test.InstrumentationTestCase;import android.view.View;import android.view.ViewGroup;import android.widget.Button;import android.widget.TextView;import android.view.accessibility.AccessibilityNodeInfo;import java.util.ArrayList;import java.util.List;
public class InventoryUiTest extends InstrumentationTestCase {
 private Activity activity;
 private void texts(View v,List<String> out){if(v instanceof TextView)out.add(((TextView)v).getText().toString());if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)texts(g.getChildAt(i),out);}}
 private boolean has(String text){List<String> values=new ArrayList<>();getInstrumentation().runOnMainSync(()->texts(activity.getWindow().getDecorView(),values));return values.stream().anyMatch(v->v.contains(text));}
 private void expect(String text)throws Exception{for(int i=0;i<100;i++){if(has(text))return;Thread.sleep(100);}fail("Missing: "+text);}
 private Button find(View v,String text){if(v instanceof Button&&((Button)v).getText().toString().equals(text))return (Button)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){Button b=find(g.getChildAt(i),text);if(b!=null)return b;}}return null;}
 private void click(String text)throws Exception{for(int i=0;i<100;i++){List<Boolean> found=new ArrayList<>();getInstrumentation().runOnMainSync(()->{Button b=find(activity.getWindow().getDecorView(),text);if(b!=null&&b.isEnabled()){b.performClick();found.add(true);}});if(!found.isEmpty())return;Thread.sleep(100);}fail("Button missing/disabled: "+text);}
 private void disabled(String text){getInstrumentation().runOnMainSync(()->{Button b=find(activity.getWindow().getDecorView(),text);assertNotNull(b);assertFalse(b.isEnabled());});}
 private void dialog(String text)throws Exception{for(int i=0;i<50;i++){AccessibilityNodeInfo root=getInstrumentation().getUiAutomation().getRootInActiveWindow();if(root!=null)for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText(text)){if(n.getText()!=null&&n.getText().toString().equalsIgnoreCase(text) ){android.graphics.Rect bounds=new android.graphics.Rect();n.getBoundsInScreen(bounds);long time=android.os.SystemClock.uptimeMillis();getInstrumentation().sendPointerSync(android.view.MotionEvent.obtain(time,time,android.view.MotionEvent.ACTION_DOWN,bounds.centerX(),bounds.centerY(),0));getInstrumentation().sendPointerSync(android.view.MotionEvent.obtain(time,time+30,android.view.MotionEvent.ACTION_UP,bounds.centerX(),bounds.centerY(),0));return;}}Thread.sleep(100);}fail("Dialog missing: "+text);}
 private void scan(String code){getInstrumentation().getContext().sendBroadcast(new Intent(BuildConfig.APPLICATION_ID+".BARCODE").setPackage(BuildConfig.APPLICATION_ID).putExtra("data",code));}
 private android.widget.EditText edit(View v,String hint){if(v instanceof android.widget.EditText&&hint.equals(String.valueOf(((android.widget.EditText)v).getHint())))return (android.widget.EditText)v;if(v instanceof ViewGroup){ViewGroup group=(ViewGroup)v;for(int i=0;i<group.getChildCount();i++){android.widget.EditText e=edit(group.getChildAt(i),hint);if(e!=null)return e;}}return null;}
 private void fill(String hint,String value){getInstrumentation().runOnMainSync(()->{android.widget.EditText e=edit(activity.getWindow().getDecorView(),hint);assertNotNull("Field "+hint,e);e.setText(value);});}
 private boolean dialogInput(AccessibilityNodeInfo node,String value){if(node==null)return false;if("android.widget.EditText".contentEquals(node.getClassName())){android.os.Bundle args=new android.os.Bundle();args.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);return node.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,args);}for(int i=0;i<node.getChildCount();i++)if(dialogInput(node.getChild(i),value))return true;return false;}
 private void searchInput(String value)throws Exception{for(int i=0;i<50;i++){if(dialogInput(getInstrumentation().getUiAutomation().getRootInActiveWindow(),value))return;Thread.sleep(100);}fail("Search field");}
 private void save(String quantity)throws Exception{fill("Np. 12",quantity);fill("Np. A-01 lub regał A, półka 2","A-01");click("Zapisz karton");dialog("Zapisz");}
 public void testInventoryCountsAndUnknownBarcodeMapping()throws Exception{
 activity=getInstrumentation().startActivitySync(new Intent(getInstrumentation().getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
 if(has("Spakowane")){click("Wróć do pakowania");expect("Do pakowania: 0");click("Wróć do zamówień");}
 expect("Zamówienia");click("Etykiety na magazynie");expect("Policzono 0 kartonów · 0 rolek");scan("3016724-T");expect("Policz rolki");save("12");expect("Zapisano karton K-0001");expect("Policzono 1 karton · 12 rolek");
 scan("3016724-T");expect("Policz rolki");save("5");expect("Zapisano karton K-0002");expect("Policzono 2 kartony · 17 rolek");
 scan("5900000001234");expect("Nie znaleziono produktu");click("Szukaj w katalogu TAKMA");searchInput("01600BK11030");dialog("Szukaj");expect("Znaleziono 1 wariant");click("01600BK11030 · Taśma termotransferowa Zebra 1600 Wax\n110×300 mm/m");expect("Policz rolki");save("3");expect("Zapisano karton K-0003");expect("Policzono 3 kartony · 20 rolek");
 scan("5900000001234");expect("Policz rolki");save("4");expect("Zapisano karton K-0004");expect("Policzono 4 kartony · 24 rolki");
 }
 private void phase(String value){android.os.Bundle status=new android.os.Bundle();status.putString("phase",value);getInstrumentation().sendStatus(2,status);}
 public void testPendingCountSurvivesNetworkLossAndRecreation()throws Exception{
 activity=getInstrumentation().startActivitySync(new Intent(getInstrumentation().getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));expect("Zamówienia");click("Etykiety na magazynie");expect("Policzono 4 kartony · 19 rolek");scan("3016724-T");expect("Policz rolki");fill("Np. 12","2");click("Zapisz karton");phase("DISCONNECT");Thread.sleep(1200);dialog("Zapisz");expect("Potwierdź zapis kartonu");expect("Brak połączenia");
 android.app.Instrumentation.ActivityMonitor monitor=getInstrumentation().addMonitor(MainActivity.class.getName(),null,false);getInstrumentation().runOnMainSync(()->activity.recreate());activity=getInstrumentation().waitForMonitorWithTimeout(monitor,10000);getInstrumentation().removeMonitor(monitor);assertNotNull(activity);expect("Potwierdź zapis kartonu");expect("Brak połączenia");phase("RECONNECT");Thread.sleep(1200);click("Sprawdź zapis kartonu");expect("Zapisano karton K-0006");expect("Policzono 5 kartonów · 21 rolek");
 }
 public void testResetBeforeOwnWarehouse()throws Exception{activity=getInstrumentation().startActivitySync(new Intent(getInstrumentation().getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));expect("Zamówienia");click("Ustawienia terminala");click("Aktywuj ponownie przez QR");dialog("Przygotuj terminal");expect("Zeskanuj kod QR");}
 public void testPrepareCloudActivation()throws Exception{activity=getInstrumentation().startActivitySync(new Intent(getInstrumentation().getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(int i=0;i<100;i++){if(has("Zaloguj się")){fill("np. magazyn","magazyn");fill("6–12 cyfr","123456");click("Zaloguj się");break;}List<Boolean> ready=new ArrayList<>();getInstrumentation().runOnMainSync(()->ready.add(find(activity.getWindow().getDecorView(),"Ustawienia terminala")!=null));if(ready.get(0))break;Thread.sleep(100);}expect("Zamówienia");click("Ustawienia terminala");click("Aktywuj ponownie przez QR");dialog("Przygotuj terminal");expect("Zeskanuj kod QR");}
 public void testActivateOwnWarehouseWithoutCounts()throws Exception{String qr=((android.test.InstrumentationTestRunner)getInstrumentation()).getArguments().getString("activationQr");assertNotNull(qr);activity=getInstrumentation().startActivitySync(new Intent(getInstrumentation().getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));getInstrumentation().waitForIdleSync();scan(qr);expect("Zamówienia");click("Etykiety na magazynie");expect("MAGAZYN TAKMA — WŁASNE STANY");expect("Policzono 0 kartonów · 0 rolek");}
 public void testStockIssueAndInvalidQuantity()throws Exception{activity=getInstrumentation().startActivitySync(new Intent(getInstrumentation().getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));expect("Zamówienia");click("Wydaj z magazynu");expect("Dostępne w magazynie: 12 rolek");scan("3007453");expect("Ile rolek pobierasz?");fill("Np. 1","13");click("Potwierdź wydanie");getInstrumentation().runOnMainSync(()->assertNotNull(edit(activity.getWindow().getDecorView(),"Np. 1").getError()));fill("Np. 1","3");fill("Np. wysyłka zamówienia","TEST — wydanie");click("Potwierdź wydanie");dialog("Wydaj");expect("Wydano 3 rolki");expect("Dostępne w magazynie: 9 rolek");scan("3007453");expect("Dostępne: 9 rolek");fill("Np. 1","10");click("Potwierdź wydanie");getInstrumentation().runOnMainSync(()->assertNotNull(edit(activity.getWindow().getDecorView(),"Np. 1").getError()));click("Anuluj wydanie");expect("Dostępne w magazynie: 9 rolek");}
 public void testPendingIssueSurvivesConnectionFailureAndRecreation()throws Exception{activity=getInstrumentation().startActivitySync(new Intent(getInstrumentation().getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));expect("Zamówienia");click("Wydaj z magazynu");expect("Dostępne w magazynie: 9 rolek");scan("3007453");expect("Ile rolek pobierasz?");fill("Np. 1","2");click("Potwierdź wydanie");java.lang.reflect.Field base=MainActivity.class.getDeclaredField("base");base.setAccessible(true);getInstrumentation().runOnMainSync(()->{try{base.set(activity,"http://127.0.0.1:8787");}catch(Exception e){throw new RuntimeException(e);}});dialog("Wydaj");expect("Potwierdź zapis wydania");expect("Brak połączenia");android.app.Instrumentation.ActivityMonitor monitor=getInstrumentation().addMonitor(MainActivity.class.getName(),null,false);getInstrumentation().runOnMainSync(()->activity.recreate());activity=getInstrumentation().waitForMonitorWithTimeout(monitor,10000);getInstrumentation().removeMonitor(monitor);assertNotNull(activity);expect("Wydano 2 rolki");expect("Dostępne w magazynie: 7 rolek");}
 public void testOpenStockWithoutWriting()throws Exception{activity=getInstrumentation().startActivitySync(new Intent(getInstrumentation().getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));expect("Zamówienia");click("Wydaj z magazynu");expect("MAGAZYN TAKMA — WYDANIE ROLEK");expect("Kod produktu");}

 public void testShelfSavedOnSeparateTestAccount()throws Exception{activity=getInstrumentation().startActivitySync(new Intent(getInstrumentation().getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(int i=0;i<100;i++){if(has("Zaloguj się")){fill("np. magazyn","magazyn");fill("6–12 cyfr","123456");click("Zaloguj się");break;}List<Boolean> ready=new ArrayList<>();getInstrumentation().runOnMainSync(()->ready.add(find(activity.getWindow().getDecorView(),"Etykiety na magazynie")!=null));if(ready.get(0))break;Thread.sleep(100);}expect("Zamówienia");click("Etykiety na magazynie");expect("MAGAZYN TAKMA — WŁASNE STANY");expect("Policzono 0 kartonów · 0 rolek");android.os.Bundle args=((android.test.InstrumentationTestRunner)getInstrumentation()).getArguments();getInstrumentation().runOnMainSync(()->{try{for(String key:new String[]{"deviceToken","sessionToken","company","worker"}){java.lang.reflect.Field field=MainActivity.class.getDeclaredField(key);field.setAccessible(true);field.set(activity,key.equals("deviceToken")?args.getString("testDevice"):key.equals("sessionToken")?args.getString("testSession"):"Test półek");}java.lang.reflect.Method method=MainActivity.class.getDeclaredMethod("loadInventory");method.setAccessible(true);method.invoke(activity);}catch(Exception e){throw new RuntimeException(e);}});expect("INWENTARYZACJA TESTOWA");scan("3007453");expect("Policz rolki");fill("Np. 12","2");fill("Np. A-01 lub regał A, półka 2","A-03");click("Zapisz karton");dialog("Zapisz");expect("Zapisano karton K-0001");expect("Policzono 1 karton · 2 rolki");}

}
